import{_ as n,C as d,o as s,c as e,a3 as t,j as i,E as l,a as o}from"./chunks/framework.C6R8kWFE.js";const z=JSON.parse('{"title":"6-dars (Mentor). Android Studio va Android SDK bilan tanishuv (1-qism)","description":"","frontmatter":{"title":"6-dars (Mentor). Android Studio va Android SDK bilan tanishuv (1-qism)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (Android)","link":"/mentor/9-sinf-android/"},"week":{"n":2,"link":"/mentor/9-sinf-android/hafta-02/"},"g":6,"title":"Android Studio va Android SDK bilan tanishuv (1-qism)","lead":"Android Studio va Android SDK bilan tanishuv (1-qism): Android Studio interfeysi, SDK Manager va SDK Build-Tools","slide":"/slaydlar/9-sinf-android/hafta-02/dars-3.html","test":"/slaydlar/9-sinf-android/hafta-02/dars-3-test.html","student_link":"/9-sinf-android/hafta-02/dars-3","tabs":[{"g":4,"link":"/mentor/9-sinf-android/hafta-02/dars-1","current":false},{"g":5,"link":"/mentor/9-sinf-android/hafta-02/dars-2","current":false},{"g":6,"link":"/mentor/9-sinf-android/hafta-02/dars-3","current":true}],"prev":{"g":5,"title":"Android ekotizimi va Google xizmatlari (2-qism)","link":"/mentor/9-sinf-android/hafta-02/dars-2"},"next":null}},"headers":[],"relativePath":"mentor/9-sinf-android/hafta-02/dars-3.md","filePath":"mentor/9-sinf-android/hafta-02/dars-3.md"}'),h={name:"mentor/9-sinf-android/hafta-02/dars-3.md"},u={class:"blk"},g={id:"_1-dars-maqsadi-va-kutiladigan-natijalar",tabindex:"-1"},m={class:"blk"},b={id:"_2-dars-rejasi-80-daqiqa",tabindex:"-1"},c={class:"blk"},k={id:"_3-nazariy-tushunchalar-mentor-uchun-to-liq-konspekt",tabindex:"-1"},y={class:"blk"},v={id:"_4-darsda-bajariladigan-amaliy-topshiriqlar-va-yechimlari",tabindex:"-1"},q={class:"blk"},f={id:"_5-tezkor-savol-javob-blits-savollar",tabindex:"-1"},p={class:"blk"},A={id:"_6-mentor-uchun-amaliy-tavsiyalar",tabindex:"-1"};function _(D,a,S,T,x,K){const r=d("Icon");return s(),e("div",null,[a[18]||(a[18]=t("<p><strong>Sinf:</strong> 9-sinf (Android dasturlash)<br><strong>Hafta:</strong> 2-hafta<br><strong>Dars tartibi:</strong> 6-dars (umumiy 102 darsdan 6-darsi)<br><strong>Davomiyligi:</strong> 80 daqiqa<br><strong>Format:</strong> Amaliy va laboratoriya mashg&#39;uloti</p><hr>",2)),i("div",u,[i("h2",g,[l(r,{name:"file-text"}),a[0]||(a[0]=o(" 1. Dars maqsadi va kutiladigan natijalar ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#_1-dars-maqsadi-va-kutiladigan-natijalar","aria-label":'Permalink to "<Icon name="file-text" /> 1. Dars maqsadi va kutiladigan natijalar"'},"​",-1))]),a[2]||(a[2]=t("<ul><li><strong>Maqsad:</strong> O&#39;quvchilarga Android ilovalari yaratishning rasmiy dasturlash muhiti — Android Studio interfeysi, uning ichki tuzilishi, Android SDK arxitekturasi (Platform-Tools, Build-Tools, SDK Platforms) hamda ADB vositasi bilan ishlash asoslarini o&#39;rgatish.</li><li><strong>Kutiladigan natijalar:</strong><ul><li>O&#39;quvchi Android Studio interfeysining asosiy oynalari (Project Explorer, Editor, Logcat, Gradle) vazifasini biladi;</li><li>Android SDK (Software Development Kit) arxitekturasining 3 ta asosiy tarkibiy qismini tushunadi;</li><li>SDK Manager oynasi orqali kerakli Android platformalari va vositalarini boshqara oladi;</li><li>ADB (Android Debug Bridge) vositasining vazifasini va asosiy buyruqlarini (<code>adb devices</code>, <code>adb logcat</code>) biladi;</li><li>Build-Tools tarkibidagi <code>aapt2</code> va <code>d8</code> kompilyatorlarining kodni yig&#39;ishdagi rolini anglaydi.</li></ul></li></ul><hr>",2))]),i("div",m,[i("h2",b,[l(r,{name:"file-text"}),a[3]||(a[3]=o(" 2. Dars rejasi (80 daqiqa) ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#_2-dars-rejasi-80-daqiqa","aria-label":'Permalink to "<Icon name="file-text" /> 2. Dars rejasi (80 daqiqa)"'},"​",-1))]),a[5]||(a[5]=t('<table tabindex="0"><thead><tr><th>Vaqt</th><th>Bosqich</th><th>Tavsif</th></tr></thead><tbody><tr><td><strong>00–10 daq</strong></td><td>O&#39;tgan mavzuni takrorlash va kirish</td><td>SHA-1 kalitlari, google-services.json va AAB formati bo&#39;yicha blits-savol. Muammoli savol: &quot;Dasturchi kod yozganda uni telefonda ishlaydigan dasturga kim aylantiradi?&quot;</td></tr><tr><td><strong>10–30 daq</strong></td><td>Yangi mavzu: Android Studio muhiti</td><td>JetBrains va Google hamkorligi, IntelliJ IDEA negizi, Android Studio interfeysi bo&#39;ylab ekskursiya</td></tr><tr><td><strong>30–50 daq</strong></td><td>Yangi mavzu: Android SDK arxitekturasi</td><td>SDK nima, SDK Platforms (API versiyalari), SDK Platform-Tools (ADB), SDK Build-Tools (aapt2, d8/r8)</td></tr><tr><td><strong>50–65 daq</strong></td><td>Amaliy mashq: SDK Manager va ADB</td><td>SDK Manager oynasini ochish, o&#39;rnatilgan paketlarni ko&#39;rish, terminalda <code>adb version</code> va <code>adb devices</code> buyruqlarini tekshirish</td></tr><tr><td><strong>65–75 daq</strong></td><td>Mustahkamlash va test sinovi</td><td>Asosiy terminlar va qisqa amaliy topshiriqlar tahlili</td></tr><tr><td><strong>75–80 daq</strong></td><td>Xulosa va 2-hafta sarhisobi</td><td>Darsni yakunlash, 2-hafta bo&#39;yicha baholash va uyga vazifa berish</td></tr></tbody></table><hr>',2))]),i("div",c,[i("h2",k,[l(r,{name:"file-text"}),a[6]||(a[6]=o(" 3. Nazariy tushunchalar (Mentor uchun to'liq konspekt) ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#_3-nazariy-tushunchalar-mentor-uchun-to-liq-konspekt","aria-label":`Permalink to "<Icon name="file-text" /> 3. Nazariy tushunchalar (Mentor uchun to'liq konspekt)"`},"​",-1))]),a[8]||(a[8]=t('<h3 id="_3-1-android-studio-—-rasmiy-dasturlash-muhiti-ide" tabindex="-1">3.1. Android Studio — rasmiy dasturlash muhiti (IDE) <a class="header-anchor" href="#_3-1-android-studio-—-rasmiy-dasturlash-muhiti-ide" aria-label="Permalink to &quot;3.1. Android Studio — rasmiy dasturlash muhiti (IDE)&quot;">​</a></h3><p>Android Studio — bu Google tomonidan JetBrains kompaniyasining IntelliJ IDEA muhiti negizida ishlab chiqilgan rasmiy integratsiyalashgan dasturlash muhitidir (Integrated Development Environment — IDE). Asosiy qulayliklari:</p><ol><li><strong>Intellektual kod muharriri:</strong> Kotlin va Java kodini avtomatik to&#39;ldirish (Code Completion), sintaktik xatolarni real vaqtda ko&#39;rsatish;</li><li><strong>Kengaytirilgan Layout Editor:</strong> XML va Jetpack Compose interfeyslarini vizual va kod ko&#39;rinishida loyihalash;</li><li><strong>Logcat konsoli:</strong> Ilovaning ishlash jarayonidagi barcha xabarlar va xatoliklarni kuzatuvchi oyna;</li><li><strong>Gradle tizimi:</strong> Loyihaning barcha tashqi kutubxonalari va yig&#39;ish parametrlarini avtomatlashtiruvchi dvigatel.</li></ol><h3 id="_3-2-android-sdk-nima-va-uning-tarkibi" tabindex="-1">3.2. Android SDK nima va uning tarkibi <a class="header-anchor" href="#_3-2-android-sdk-nima-va-uning-tarkibi" aria-label="Permalink to &quot;3.2. Android SDK nima va uning tarkibi&quot;">​</a></h3><p><strong>Android SDK (Software Development Kit)</strong> — bu operatsion tizim bilan muloqot qilish, kodni kompilyatsiya qilish va ilovani yig&#39;ish uchun zarur bo&#39;lgan barcha texnik asbob-uskunalar to&#39;plamidir. U 3 ta asosiy ustundan iborat:</p><h4 id="_1-sdk-platforms" tabindex="-1">1. SDK Platforms <a class="header-anchor" href="#_1-sdk-platforms" aria-label="Permalink to &quot;1. SDK Platforms&quot;">​</a></h4><ul><li>Har bir Android versiyasi (masalan, Android 14 — API 34, Android 15 — API 35) uchun mo&#39;ljallangan platforma kutubxonalari (<code>android.jar</code>).</li><li>Dasturchi qaysi versiya uchun kod yozmoqchi bo&#39;lsa, SDK Manager orqali o&#39;sha platformani yuklab oladi.</li></ul><h4 id="_2-sdk-platform-tools-adb" tabindex="-1">2. SDK Platform-Tools (ADB) <a class="header-anchor" href="#_2-sdk-platform-tools-adb" aria-label="Permalink to &quot;2. SDK Platform-Tools (ADB)&quot;">​</a></h4><ul><li>Eng asosiysi — <strong>ADB (Android Debug Bridge)</strong>.</li><li>ADB kompyuter va Android qurilma (yoki emulyator) o&#39;rtasida ma&#39;lumot uzatuvchi mijoz-server ko&#39;prigidir: <ul><li><code>adb devices</code> — kompyuterga ulangan barcha telefon va virtual qurilmalar ro&#39;yxatini ko&#39;rsatadi;</li><li><code>adb install app.apk</code> — kompyuterdan telefonga ilovani o&#39;rnatadi;</li><li><code>adb logcat</code> — telefon ichidagi xatolar va tizim loglarini to&#39;g&#39;ridan-to&#39;g&#39;ri terminalga oqim sifatida chiqaradi;</li><li><code>adb shell</code> — telefonning Linux buyruqlar qatoriga (terminaliga) kirish imkonini beradi.</li></ul></li></ul><h4 id="_3-sdk-build-tools" tabindex="-1">3. SDK Build-Tools <a class="header-anchor" href="#_3-sdk-build-tools" aria-label="Permalink to &quot;3. SDK Build-Tools&quot;">​</a></h4><p>Loyihani kompilyatsiya qilish va APK/AAB fayliga aylantirish asboblari:</p><ul><li><strong><code>aapt2</code> (Android Asset Packaging Tool 2):</strong> Loyihaning barcha resurslarini (XML maketlar, ranglar, rasmlar) tekshirib, binar formatga paketlaydi;</li><li><strong><code>d8</code> / <code>r8</code>:</strong> Java baytkodini (<code>.class</code>) Android Runtime tushunadigan <code>.dex</code> baytkodiga o&#39;tkazuvchi va keraksiz kodlarni tozalovchi (Shrinking &amp; Obfuscation) zamonaviy kompilyatordir.</li></ul><h3 id="_3-3-sdk-manager-bilan-ishlash" tabindex="-1">3.3. SDK Manager bilan ishlash <a class="header-anchor" href="#_3-3-sdk-manager-bilan-ishlash" aria-label="Permalink to &quot;3.3. SDK Manager bilan ishlash&quot;">​</a></h3><p>Android Studio yuqori o&#39;ng burchagidagi &quot;SDK Manager&quot; belgisi orqali boshqariladi:</p><ul><li><strong>SDK Platforms yorlig&#39;i:</strong> Kerakli Android API darajalarini tanlash va o&#39;rnatish;</li><li><strong>SDK Tools yorlig&#39;i:</strong> Android SDK Build-Tools, Android Emulator, Android SDK Platform-Tools, Google Play Services komponentlarini yangilash.</li></ul><hr>',16))]),i("div",y,[i("h2",v,[l(r,{name:"file-text"}),a[9]||(a[9]=o(" 4. Darsda bajariladigan amaliy topshiriqlar va yechimlari ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#_4-darsda-bajariladigan-amaliy-topshiriqlar-va-yechimlari","aria-label":'Permalink to "<Icon name="file-text" /> 4. Darsda bajariladigan amaliy topshiriqlar va yechimlari"'},"​",-1))]),a[11]||(a[11]=t('<h3 id="_1-topshiriq-android-sdk-tarkibiy-qismlari-matritsasi-oson" tabindex="-1">1-topshiriq. Android SDK tarkibiy qismlari matritsasi (Oson) <a class="header-anchor" href="#_1-topshiriq-android-sdk-tarkibiy-qismlari-matritsasi-oson" aria-label="Permalink to &quot;1-topshiriq. Android SDK tarkibiy qismlari matritsasi (Oson)&quot;">​</a></h3><p><strong>Topshiriq:</strong> SDK Platforms, SDK Platform-Tools va SDK Build-Tools o&#39;rtasidagi farqni bittadan aniq vosita misolida jadvalga yozing.</p><p><strong>Yechim:</strong></p><table tabindex="0"><thead><tr><th>SDK qismi</th><th>Asosiy vazifasi</th><th>Tarkibidagi vosita / misol</th></tr></thead><tbody><tr><td><strong>SDK Platforms</strong></td><td>Muayyan Android versiyasining API kutubxonalari</td><td>Android 14 (API 34) <code>android.jar</code></td></tr><tr><td><strong>SDK Platform-Tools</strong></td><td>Qurilma bilan aloqa va testlash</td><td><code>adb</code> (Android Debug Bridge)</td></tr><tr><td><strong>SDK Build-Tools</strong></td><td>Resurslarni paketlash va kodni kompilyatsiya qilish</td><td><code>aapt2</code>, <code>d8</code> kompilyatori</td></tr></tbody></table><h3 id="_2-topshiriq-adb-buyruqlari-tahlili-o-rta" tabindex="-1">2-topshiriq. ADB buyruqlari tahlili (O&#39;rta) <a class="header-anchor" href="#_2-topshiriq-adb-buyruqlari-tahlili-o-rta" aria-label="Permalink to &quot;2-topshiriq. ADB buyruqlari tahlili (O&#39;rta)&quot;">​</a></h3><p><strong>Topshiriq:</strong> Quyidagi 3 ta ADB buyrug&#39;i nima vazifa bajarishini tushuntiring:</p><ol><li><code>adb devices</code></li><li><code>adb install myapp.apk</code></li><li><code>adb logcat -s &quot;MyAppTag&quot;</code></li></ol><p><strong>Yechim:</strong></p><ol><li><code>adb devices</code>: Kompyuterga USB yoki Wi-Fi orqali ulangan barcha faol Android qurilmalar va emulyatorlar ro&#39;yxatini va ularning holatini (<code>device</code> yoki <code>unauthorized</code>) chiqaradi.</li><li><code>adb install myapp.apk</code>: Ko&#39;rsatilgan APK faylini to&#39;g&#39;ridan-to&#39;g&#39;ri ulangan telefonga o&#39;rnatadi.</li><li><code>adb logcat -s &quot;MyAppTag&quot;</code>: Telefondan kelayotgan ulkan tizim xabarlari oqimidan faqat <code>MyAppTag</code> belgisi qo&#39;yilgan xabarlarni filtrlab terminalda ko&#39;rsatadi.</li></ol><h3 id="_3-topshiriq-aapt2-va-d8-kompilyatorlari-zanjiri-qiyin" tabindex="-1">3-topshiriq. aapt2 va d8 kompilyatorlari zanjiri (Qiyin) <a class="header-anchor" href="#_3-topshiriq-aapt2-va-d8-kompilyatorlari-zanjiri-qiyin" aria-label="Permalink to &quot;3-topshiriq. aapt2 va d8 kompilyatorlari zanjiri (Qiyin)&quot;">​</a></h3><p><strong>Topshiriq:</strong> Dasturchi &quot;Run&quot; (Ishga tushirish) tugmasini bosgandan to APK hosil bo&#39;lguncha <code>aapt2</code> va <code>d8</code> qanday ketma-ketlikda ishtirok etadi? Sxema ko&#39;rinishida yozing.</p><p><strong>Yechim:</strong></p><ol><li><strong>1-bosqich:</strong> Dasturchi yozgan Kotlin/Java kodi <code>kotlinc</code> / <code>javac</code> tomonidan <code>.class</code> baytkodiga aylanadi.</li><li><strong>2-bosqich (<code>aapt2</code>):</strong> Loyihaning barcha XML fayllari, rasmlari va resurslari tekshirilib, binar formatga o&#39;tkaziladi va <code>R.java</code> fayli yaratiladi.</li><li><strong>3-bosqich (<code>d8</code>):</strong> Barcha <code>.class</code> fayllari va tashqi kutubxonalar Android tushunadigan <code>.dex</code> (Dalvik Executable) formatiga o&#39;giriladi.</li><li><strong>4-bosqich:</strong> <code>.dex</code> kodlari va <code>aapt2</code> tayyorlagan resurslar birlashtirilib, raqamli imzo bilan bitta APK/AAB paketi yig&#39;iladi.</li></ol><hr>',14))]),i("div",q,[i("h2",f,[l(r,{name:"file-text"}),a[12]||(a[12]=o(" 5. Tezkor savol-javob (Blits-savollar) ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#_5-tezkor-savol-javob-blits-savollar","aria-label":'Permalink to "<Icon name="file-text" /> 5. Tezkor savol-javob (Blits-savollar)"'},"​",-1))]),a[14]||(a[14]=t("<ol><li><strong>Android Studio qaysi mashhur IDE negizida yaratilgan?</strong><br><em>Javob:</em> JetBrains IntelliJ IDEA negizida.</li><li><strong>ADB qisqartmasi nimani anglatadi?</strong><br><em>Javob:</em> Android Debug Bridge (Android nosozliklarni tuzatish ko&#39;prigi).</li><li><strong>Qurilma bilan kompyuter aloqasini tekshirish uchun qaysi buyruq kiritiladi?</strong><br><em>Javob:</em> <code>adb devices</code>.</li><li><strong>XML resurslarni paketlash uchun SDK tarkibidagi qaysi vosita mas&#39;ul?</strong><br><em>Javob:</em> <code>aapt2</code> (Android Asset Packaging Tool 2).</li><li><strong>Java baytkodini <code>.dex</code> kodga qaysi zamonaviy vosita o&#39;tkazadi?</strong><br><em>Javob:</em> <code>d8</code> kompilyatori (yoki kodni qisqartiruvchi <code>r8</code>).</li></ol><hr>",2))]),i("div",p,[i("h2",A,[l(r,{name:"file-text"}),a[15]||(a[15]=o(" 6. Mentor uchun amaliy tavsiyalar ",-1)),a[16]||(a[16]=i("a",{class:"header-anchor",href:"#_6-mentor-uchun-amaliy-tavsiyalar","aria-label":'Permalink to "<Icon name="file-text" /> 6. Mentor uchun amaliy tavsiyalar"'},"​",-1))]),a[17]||(a[17]=i("ul",null,[i("li",null,"Sinf kompyuterida Android Studio dasturini ochib, SDK Manager oynasini ekranda jonli ko'rsating."),i("li",null,[o("Terminalda "),i("code",null,"adb version"),o(" buyrug'ini ishlatib ko'rsatish orqali, o'quvchilarda buyruqlar satri bilan ishlashga nisbatan qo'rquvni yo'qoting.")]),i("li",null,"Keyingi haftada loyihaning ichki fayl tuzilmasi (java, res, manifest, gradle) va birinchi «Hello World» dasturini yaratishimizni aytib o'ting.")],-1))])])}const I=n(h,[["render",_]]);export{z as __pageData,I as default};
